#include <print>
#include <vector>

int main() {
    std::vector<int> d(6, 0);                     // 5 个人，多开 1 格当刹车位
    d[1] += 10;  d[4] -= 10;                      // 第 2~4 人各 +10
    d[2] += 5;   d[5] -= 5;                       // 第 3~5 人各 +5
    d[0] -= 3;   d[5] += 3;                       // 第 1~5 人各 -3：桩在 0 和 5
    for (int i = 0; i < 6; ++i) std::print("d[{}]={} ", i, d[i]);
    std::println("");
    int cur = 0;
    for (int i = 0; i < 5; ++i) { cur += d[i]; std::print("第{}人={} ", i + 1, cur); }
    std::println("");
    return 0;
}
// 还原后第 1 人 = -3，第 5 人 = 2；两根桩落在 0 和 5 这两格

